def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    words = []
    for _ in range(n):
        words.append(next(iterator))

    # Group words by length for efficient lookup
    from collections import defaultdict
    by_length = defaultdict(list)
    for w in words:
        by_length[len(w)].append(w)

    # Store original indices to maintain output order
    indexed_words = list(enumerate(words))
    typos = []

    # We only need to check words that are longer than the minimum length
    # because a typo must reduce length by exactly 1.
    min_len = min(len(w) for w in words)
    max_len = max(len(w) for w in words)

    # Precompute a set of all words for O(1) lookup
    word_set = set(words)

    # For each word, check if deleting one character results in another word in the dictionary
    for i, w in enumerate(words):
        l = len(w)
        # Optimization: if the word is the shortest, it can't be a typo
        if l <= min_len:
            continue

        is_typo = False
        # Try deleting each character
        for j in range(l):
            # Create the new word by skipping character at index j
            new_word = w[:j] + w[j+1:]
            if new_word in word_set:
                is_typo = True
                break

        if is_typo:
            typos.append(w)

    if not typos:
        print("NO TYPOS")
    else:
        for t in typos:
            print(t)

